// Código VULNERÁVEL - SQL Injection
import java.sql.*;

public class UsuarioDAO {
    public Usuario buscarUsuario(String email) throws SQLException {
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/db", "user", "pass");

        // VULNERÁVEL: Concatenação direta de entrada do usuário na query
        String query = "SELECT * FROM usuarios WHERE email = '" + email + "'";
        Statement stmt = conn.createStatement();
        ResultSet rs = stmt.executeQuery(query);

        if (rs.next()) {
            return new Usuario(rs.getInt("id"), rs.getString("email"));
        }
        return null;
    }
}
