// Código SEGURO - Desserialização com validação de classe
import java.io.*;

public class SerializacaoSegura {
    private static final List<String> CLASSES_PERMITIDAS = Arrays.asList(
        "com.exemplo.Usuario",
        "com.exemplo.Produto"
    );

    public Object desserializarDados(byte[] dados) throws IOException, ClassNotFoundException {
        ByteArrayInputStream bais = new ByteArrayInputStream(dados);

        // SEGURO: Validação de classe antes da desserialização
        ObjectInputStream ois = new ObjectInputStream(bais) {
            @Override
            protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
                if (!CLASSES_PERMITIDAS.contains(desc.getName())) {
                    throw new InvalidClassException("Classe não permitida: " + desc.getName());
                }
                return super.resolveClass(desc);
            }
        };

        Object objeto = ois.readObject();
        ois.close();

        return objeto;
    }
}
```

