// Código SEGURO - Execução de comando com validação e array
import java.io.*;
import java.util.regex.*;

public class ExecucaoComandoSegura {
    private static final Pattern COMANDO_VALIDO = Pattern.compile("^[a-zA-Z0-9_-]+$");

    public String executarComando(String comando) throws IOException {
        // SEGURO: Validação de entrada e uso de array em vez de string
        if (!COMANDO_VALIDO.matcher(comando).matches()) {
            throw new IllegalArgumentException("Comando inválido");
        }

        // Usar array evita interpretação de shell
        String[] cmd = {"/bin/sh", "-c", comando};
        Process processo = Runtime.getRuntime().exec(cmd);

        BufferedReader reader = new BufferedReader(
            new InputStreamReader(processo.getInputStream())
        );

        return reader.readLine();
    }
}
